import { noopReturn } from "./utils.js";
const rotation = {
    syntax: "<angle>",
    initialValue: "0deg",
    toDefaultUnit: (v) => `${v}deg`,
};
const baseTransformProperties = {
    translate: {
        syntax: "<length-percentage>",
        initialValue: "0px",
        toDefaultUnit: (v) => `${v}px`,
    },
    rotate: rotation,
    scale: {
        syntax: "<number>",
        initialValue: 1,
        toDefaultUnit: noopReturn,
    },
    skew: rotation,
};
/**
 * An ordered array of each transformable value. By default, transform values
 * will be sorted to this order.
 */
const order = ["translate", "scale", "rotate", "skew"];
/**
 * A list of all transformable axes. We'll use this list to generated a version
 * of each axes for each transform.
 */
export const axes = ["", "X", "Y", "Z"];
export const transformDefinitions = new Map();
/**
 * Generate a list of every possible transform key
 */
const transforms = [
    "transformPerspective",
    "x",
    "y",
    "z",
    "translateX",
    "translateY",
    "translateZ",
    "scale",
    "scaleX",
    "scaleY",
    "rotate",
    "rotateX",
    "rotateY",
    "rotateZ",
    "skew",
    "skewX",
    "skewY",
];
order.forEach((name) => {
    axes.forEach((axis) => {
        transforms.push(name + axis);
        transformDefinitions.set(name + axis, baseTransformProperties[name]);
    });
});
/**
 * Provide a quick way to check if a string is the name of a transform
 */
const transformLookup = new Set(transforms);
export const isTransform = (name) => transformLookup.has(name);
export const transformAlias = {
    x: "translateX",
    y: "translateY",
    z: "translateZ",
};
export function compareTransformOrder([a], [b]) {
    return transforms.indexOf(a) - transforms.indexOf(b);
}
function transformListToString(template, [name, value]) {
    return `${template} ${name}(${value})`;
}
export function buildTransformTemplate(transforms) {
    return transforms.sort(compareTransformOrder).reduce(transformListToString, "").trim();
}
export const transformResetValue = {
    translate: [0, 0],
    rotate: 0,
    scale: 1,
    skew: 0,
    x: 0,
    y: 0,
    z: 0,
};
